  ) as v (k, canal, tipo, data, legenda)
 where t.id = i.topic_id and t.ext_key = v.k and i.channel_id = v.canal and i.link_kind = v.tipo
   and (v.data is null or i.pub_date = v.data)
   and not i.archived and i.stage <> 'publicado' and i.caption is distinct from v.legenda;

-- o padrão de legenda no Guia da marca (aparece no assunto, em "Guia da marca")
insert into public.social_strategy_notes (ext_key, section, brand, item, value, note, ord)
values
  ('padrao-legenda:playmi', 'guia', 'Playmi', 'Padrão de legenda', $q$Parágrafos corridos (300 a 650 caracteres): gancho com emoji, produto pelo nome completo e um detalhe concreto, o valor do brincar e fecho com pergunta e/ou "Onde encontrar: link na bio." Sem hashtag, sem idade solta (só quando é o argumento), sem "Brincar é crescer, juntos!".$q$, 'Tirado do que foi publicado de set a out/2026', 0),
  ('padrao-legenda:topi', 'guia', 'Tópi', 'Padrão de legenda', $q$Curta e direta (220 a 500 caracteres): gancho de ação com emoji, produto e detalhe concreto, faz de conta, pergunta para comentar e, com frequência, "Brincar é Tópi! 🧡". Emojis 💛🧡. Sem hashtag e sem idade solta.$q$, 'Tirado do que foi publicado de set a out/2026', 0),
  ('padrao-legenda:cardoso', 'guia', 'Cardoso', 'Padrão de legenda', $q$Instagram (400 a 750 caracteres): gancho-tese; a Cardoso como indústria que pensa a jornada até o ponto de venda (portfólio, Playmi e Tópi, licenças, mix, suporte comercial); o que isso significa para o lojista; fecho de contraste ("Mais do que produzir brinquedos. Criamos soluções para o varejo.") e CTA ("Toque em Enviar mensagem e fale com o nosso comercial"). LinkedIn (600 a 1.400): parágrafos curtos com linha em branco, "Na Cardoso, …", fecho reflexivo e CTA suave; hashtag só em post temático. Nunca número interno (venda, metragem, quantidade de itens).$q$, 'Tirado do que foi publicado de set a out/2026', 0)
on conflict (ext_key) do update set value = excluded.value, note = excluded.note;

-- CONFERÊNCIA — com_hashtag e assinatura_antiga têm que vir 0 (fora do LinkedIn)
select i.brand, i.channel_id, count(*) as pecas,
       count(*) filter (where i.caption ~ '#\w' and i.channel_id <> 'cd-li') as com_hashtag,
       count(*) filter (where i.caption ilike '%Brincar é crescer%') as assinatura_antiga
  from public.social_plan_items i
 where not i.archived and i.stage <> 'publicado' and i.pub_date >= '2026-11-03' and i.link_kind in ('matriz', 'adapta')
   and i.brand in ('Cardoso') and coalesce(i.ext_id, '') not like 'shorts-2026:%'
 group by 1, 2
 order by 1, 2;
